"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[826],{76939:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"server","desc":"Server entry point. Starts replication, initialises the maze singletons,\\nanswers each client\'s request for the initial world snapshot, then boots the\\nECS.\\n\\nThe order matters twice over. `bootstrap` must finish before `startup`\\nregisters any system, because system registration order is not guaranteed\\nand several systems read those singletons on their first tick. And the\\nresponder must be attached before `lync.start`, which seals what a side has\\nattached and publishes the remotes a client is waiting on.","tags":["core"],"realm":["Server"],"source":{"line":17,"path":"src/main/server/server.server.luau"}}')}}]);